package com.primehr.learningdevelopment.plan.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="ld_idp_route_step",uniqueConstraints=@UniqueConstraint(name="uk_ld_idp_route_step",columnNames={"agency_id","route_id","route_level"}))
public class LdIdpRouteStep extends RspAuditedEntity{
 public enum Action{RECOMMEND,APPROVE}public enum Status{PENDING,CURRENT,RECOMMENDED,RETURNED,APPROVED,SKIPPED}
 @Column(name="route_id",nullable=false,length=36)private String routeId;@Column(name="route_level",nullable=false)private int level;@Enumerated(EnumType.STRING)@Column(name="action_type",nullable=false,length=20)private Action action;@Column(name="employee_id",nullable=false)private Long employeeId;@Column(name="employee_no",nullable=false,length=100)private String employeeNo;@Column(name="employee_name",nullable=false,length=300)private String employeeName;@Column(name="appointment_id",nullable=false)private Long appointmentId;@Column(name="participant_fingerprint",nullable=false,length=64)private String participantFingerprint;@Column(name="organization_fingerprint",nullable=false,length=64)private String organizationFingerprint;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="decided_by",length=100)private String decidedBy;@Column(name="decided_at")private Instant decidedAt;@Column(name="decision_reason",length=2000)private String decisionReason;
 protected LdIdpRouteStep(){}public LdIdpRouteStep(String agency,String route,int level,Action action,Long employeeId,String employeeNo,String name,Long appointmentId,String participantFingerprint,String organizationFingerprint){super(agency);routeId=requiredText(route,"routeId");if(level<1)throw new IllegalArgumentException("level must be positive");this.level=level;this.action=action;this.employeeId=employeeId;this.employeeNo=requiredText(employeeNo,"employeeNo");employeeName=requiredText(name,"employeeName");this.appointmentId=appointmentId;this.participantFingerprint=requiredText(participantFingerprint,"participantFingerprint");this.organizationFingerprint=requiredText(organizationFingerprint,"organizationFingerprint");status=level==1?Status.CURRENT:Status.PENDING;}public void decide(Status result,String actor,String reason,Instant at){if(status!=Status.CURRENT)throw new IllegalStateException("Only the current route step may be decided");status=result;decidedBy=requiredText(actor,"actor");decisionReason=optionalText(reason);decidedAt=at;}public void makeCurrent(){if(status!=Status.PENDING)throw new IllegalStateException("Only a pending step may become current");status=Status.CURRENT;}public void skip(){if(status==Status.PENDING)status=Status.SKIPPED;}public String getRouteId(){return routeId;}public int getLevel(){return level;}public Action getAction(){return action;}public Long getEmployeeId(){return employeeId;}public String getEmployeeNo(){return employeeNo;}public String getEmployeeName(){return employeeName;}public Long getAppointmentId(){return appointmentId;}public String getParticipantFingerprint(){return participantFingerprint;}public String getOrganizationFingerprint(){return organizationFingerprint;}public Status getStatus(){return status;}public String getDecidedBy(){return decidedBy;}public Instant getDecidedAt(){return decidedAt;}public String getDecisionReason(){return decisionReason;}
}
